/* DEVELOPMENT_START */
const DW={list:[],current:null,projectId:null,preview:null,tab:'files',files:[],page:1,total:0,query:'',file:null,change:null,changes:[],check:null,error:'',busy:false};
const DW_DRAFT_KEY=KEY+':development-drafts-v1';
try{DW.drafts=JSON.parse(localStorage.getItem(DW_DRAFT_KEY)||'{}')}catch{DW.drafts={}}
const dwPanel=document.createElement('section');dwPanel.id='development';dwPanel.className='fl';dwPanel.hidden=true;dwPanel.setAttribute('role','dialog');dwPanel.setAttribute('aria-label','源码开发工作区');document.body.append(dwPanel);
const dwWindowsBase=dmWindows;dmWindows=()=>[...dwWindowsBase(),dwPanel];
const dwWindowKeyBase=dmWindowKey;dmWindowKey=el=>el===dwPanel?'development':dwWindowKeyBase(el);
const dwVisible=()=>DW.list.filter(w=>w.projectId?P(w.projectId)?.boardId===state.activeBoard:w.boardId===state.activeBoard);
const dwWorkspace=()=>dwVisible().find(w=>w.id===DW.current)||dwVisible()[0];
const dwDraftId=(w,p)=>w.id+'|'+p;
function dwSaveDrafts(){try{localStorage.setItem(DW_DRAFT_KEY,JSON.stringify(DW.drafts))}catch{hint('源码草稿暂未保存到本机，请先保存文件或复制草稿')}}
async function dwApi(action,args={},signal){const r=await fetch('/api/studio/development',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...args}),signal});const d=await r.json();if(!r.ok)throw new Error(d.error||'源码操作未完成');return d}
async function dwRefresh(signal){const d=await dwApi('list',{},signal);DW.list=d.workspaces;if(!dwVisible().some(w=>w.id===DW.current))DW.current=dwVisible()[0]?.id||null;return d}
async function dwFiles(){const w=dwWorkspace();if(!w)return;const d=await dwApi('files',{workspaceId:w.id,query:DW.query,page:DW.page});DW.files=d.files;DW.total=d.total;}
async function dwOpen(projectId){closePan();DW.projectId=projectId||state.room||state.sel||null;dwPanel.hidden=false;DW.error='';try{await dwRefresh();const matching=dwVisible().find(w=>w.projectId===DW.projectId);if(matching)DW.current=matching.id;const w=dwWorkspace();await dwFiles();if(w?.lastCheck){DW.check=await dwApi('checkStatus',{workspaceId:w.id,runId:w.lastCheck.id});if(!DW.check.settled)void dwFollowCheck(w,DW.check).catch(e=>hint(e.message));}}catch(e){DW.error=e.message}dwRender();}
function dwClose(){dwPanel.hidden=true;}
function dwRender(){
 if(dwPanel.hidden)return;const w=dwWorkspace(),file=DW.file,options=dwVisible();
 dwPanel.innerHTML=`<h3>${icon('code',17)}源码开发<button class="x" data-dw-close aria-label="关闭源码开发">${icon('close',16)}</button></h3><div class="dw-body"><div class="row"><button data-dt-begin>源码自开发教程</button><button data-dw-other>连接其他仓库</button></div><p class="lab">只操作所连接的源码工程；模型调用仍需明确开工。文件编辑有独立差异记录，画板撤销不会偷偷回滚磁盘。</p><div class="row"><select data-dw-workspace aria-label="选择源码工作区"><option value="">连接一个项目…</option>${options.map(x=>`<option value="${x.id}" ${w?.id===x.id?'selected':''}>${esc(P(x.projectId)?.name||x.name)}</option>`).join('')}</select><button data-dw-settings>连接设置</button>${w?'<button data-dw-detach>断开</button>':''}</div>${DW.error?`<p class="dw-error" role="alert">${esc(DW.error)}</p>`:''}${!w||DW.settings?dwConnection():`<p class="dw-location">${esc(w.root)} · ${w.writable?'允许源码写入':'只读'} · ${w.checksAllowed?'已允许项目检查':'检查未授权或脚本已变化'}</p><div class="row dw-tabs">${[['files','文件'],['changes','差异与回滚'],['checks','检查与日志']].map(([id,name])=>`<button data-dw-tab="${id}" aria-pressed="${DW.tab===id}">${name}</button>`).join('')}</div>${DW.tab==='changes'?dwChangesMarkup():DW.tab==='checks'?dwChecksMarkup(w):`<div class="dw-grid"><aside><div class="row"><input data-dw-query aria-label="筛选源码文件" value="${esc(DW.query)}" placeholder="筛选路径"><button data-dw-search>查找</button></div><p class="lab">${DW.total} 个可见文件</p><div class="dw-files">${DW.files.map(p=>`<button data-dw-file="${esc(p)}" title="${esc(p)}" aria-pressed="${file?.path===p}">${esc(p)}</button>`).join('')}</div><div class="row"><button data-dw-page="-1" ${DW.page<2?'disabled':''}>上一页</button><span>${DW.page}</span><button data-dw-page="1" ${DW.page*60>=DW.total?'disabled':''}>下一页</button></div></aside><div class="dw-editor"><div class="row"><input data-dw-path aria-label="源码文件路径" value="${esc(file?.path||'')}" placeholder="src/example.ts"><button data-dw-read-path>打开</button><button data-dw-new>新建草稿</button></div>${file?`<p class="lab">${file.dirty?'手动草稿 · 尚未保存':'磁盘实际内容'} · 已读 ${file.text.length}/${file.total} 字符${file.nextStart!==null?' · 尚未读全':''}</p><textarea data-dw-editor aria-label="源码编辑器" spellcheck="false">${esc(file.text)}</textarea><div class="row"><button data-dw-save ${!w.writable||file.nextStart!==null||file.text.length>180000?'disabled':''}>保存到源码</button><button data-dw-git>${w.kind==='practice'?'逐次差异':'Git diff'}</button><button data-dw-discard>放弃本文件草稿并重读</button>${file.nextStart!==null?'<button data-dw-more>继续读取</button>':''}<button data-dw-delete ${!w.writable?'disabled':''}>删除文件</button></div><details><summary>精确替换一处片段（适合大文件）</summary><label>唯一的原文片段<textarea data-dw-old aria-label="要替换的原文"></textarea></label><label>替换为<textarea data-dw-new-text aria-label="替换后的源码"></textarea></label><button data-dw-replace ${!w.writable?'disabled':''}>应用精确替换</button></details>`:'<p class="lab">选择文件后读取真实正文；新文件先写草稿，点保存才落盘。</p>'}</div></div>`}`}</div>`;
 dmDecorate();dwCheckPaint();
}
function dwConnection(){const p=DW.preview;return `<div class="dw-connect"><p class="lab">初次使用？独立练习工程会真实保存文件和运行测试，不需要 Git、npm 或 API；检查按本机账号执行，不是操作系统沙箱。</p><button data-dt-create>新建本地源码练习</button><hr><label>Git 仓库绝对路径<input data-dw-directory aria-label="Git仓库路径" value="${esc(p?.root||DW.directory||'')}" placeholder="/path/to/your/repository"></label><button data-dw-preview>检查目录与脚本</button>${p?`<p>${esc(p.name)} · ${esc(p.root)}</p><label>关联项目<select data-dw-project aria-label="源码关联项目"><option value="new">新建开发项目</option>${onB(state.projects).map(x=>`<option value="${x.id}" ${DW.projectId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>新项目名称<input data-dw-project-name aria-label="开发项目名称" value="${esc(DW.newName||p.name+' · 开发')}" maxlength="120"></label><label class="row"><input type="checkbox" data-dw-writable ${DW.allowWrite?'checked':''}>允许读写所选仓库的源码</label><pre>${esc(JSON.stringify(p.scripts,null,2))}</pre><p class="lab">检查运行仓库代码，使用你的本机账号权限，不是安全沙箱。开发检查需本机 Git、Node/npm；Relay 构建另需 Python。不会自动安装依赖或运行任意命令。</p><label class="row"><input type="checkbox" data-dw-grant ${DW.allowChecks?'checked':''}>允许运行上面列出的类型检查、测试和构建</label><button data-dw-attach>连接源码项目</button>`:''}</div>`}
function dwChangesMarkup(){return `<div class="dw-changes"><p class="lab">只回滚所选的一次修改。文件有后续人工改动时会拒绝覆盖。</p><button data-dw-refresh-changes>刷新差异记录</button>${DW.changes.map(c=>`<div class="row"><button data-dw-diff="${c.id}">${esc(c.path)} · ${{create:'新建',delete:'删除',edit:'修改'}[c.kind]||'修改'} · ${{applied:'已应用',reverted:'已回滚',prepared:'待核对',conflicted:'有冲突'}[c.status]||c.status}</button>${c.status==='applied'?`<button data-dw-revert="${c.id}">回滚这次修改</button>`:c.status==='reverted'?`<button data-dw-reapply="${c.id}">重做这次修改</button>`:''}</div>`).join('')||'<p class="lab">还没有通过源码工作区保存的修改。</p>'}${DW.gitDiff?`<h4>${esc(DW.gitDiff.path)} · Git diff</h4><pre>${esc(DW.gitDiff.diff||"没有已跟踪文件差异")}</pre>${DW.gitDiff.truncated?"<p class=lab>差异超过60000字符，当前显示前段。</p>":""}`:""}${DW.change?`<h4>${esc(DW.change.path)}</h4><div class="dw-compare"><label>修改前<textarea readonly aria-label="修改前的源码">${esc(DW.change.before??'（文件不存在）')}</textarea></label><label>修改后<textarea readonly aria-label="修改后的源码">${esc(DW.change.after??'（文件已删除）')}</textarea></label></div>`:''}</div>`}
function dwChecksMarkup(w){return `<p class="lab">检查退出码和日志来自真实本机进程；关闭面板不停止检查。停止后需主动重新运行。</p><div class="row">${[['typecheck','类型检查'],['test','运行测试'],['build','构建']].map(([c,n])=>`<button data-dw-check="${c}" ${!w.checksAllowed||!w.commands.includes(c)||DW.check&&!DW.check.settled?'disabled':''}>${w.kind==='practice'&&c==='typecheck'?'语法检查':n}</button>`).join('')}<button data-dw-stop ${!DW.check||DW.check.settled?'disabled':''}>停止检查</button></div><p data-dw-check-state role="status" aria-live="polite"></p><pre data-dw-log tabindex="0" aria-label="真实检查日志"></pre>`}
function dwCheckPaint(){const c=DW.check;if(!c)return;const status=dwPanel.querySelector('[data-dw-check-state]'),log=dwPanel.querySelector('[data-dw-log]');if(status)status.textContent=c.message+(Number.isInteger(c.exitCode)?' · 退出码 '+c.exitCode:'')+(c.truncated?' · 显示日志末尾，前文已超出保留上限':'');if(log&&log.textContent!==c.output){const atEnd=log.scrollTop+log.clientHeight>=log.scrollHeight-30;log.textContent=c.output;if(atEnd)log.scrollTop=log.scrollHeight;}}
async function dwRead(w,name,start=0,length=20000){const r=await dwApi('read',{workspaceId:w.id,path:name,start,length});const draft=DW.drafts[dwDraftId(w,name)];if(start&&DW.file?.path===name&&!DW.file.dirty){if(DW.file.hash!==r.hash)throw new Error('读取期间源码已变化，请重新打开文件');DW.file.text+=r.text;DW.file.nextStart=r.nextStart;DW.file.total=r.total;}else DW.file=draft?{...draft,dirty:true}:{...r,dirty:false};DW.tab='files';dwRender();return{...r,manualDraft:!!draft}}
function dwStoreDraft(){const w=dwWorkspace();if(!w||!DW.file)return;DW.file.dirty=true;DW.file.text=dwPanel.querySelector('[data-dw-editor]')?.value??DW.file.text;DW.file.total=Math.max(DW.file.total,DW.file.text.length);DW.drafts[dwDraftId(w,DW.file.path)]={...DW.file};dwSaveDrafts();}
function dwAssertClean(w,name){if(DW.drafts[dwDraftId(w,name)])throw asWaiting('此文件有未保存的手动草稿，请先保存或放弃草稿；没有覆盖你的编辑');}
async function dwChanges(){const w=dwWorkspace();if(!w)return;const d=await dwApi('diff',{workspaceId:w.id});DW.changes=d.changes;}
async function dwSaved(w,r){delete DW.drafts[dwDraftId(w,r.path)];dwSaveDrafts();if(DW.file?.path===r.path)DW.file=null;DW.change=r.id?await dwApi('diff',{workspaceId:w.id,changeId:r.id}):null;await dwChanges();await dwFiles();DW.tab='changes';dwRender();return r}
async function dwFollowCheck(w,r,signal,onProgress){DW.check=r;DW.tab='checks';dwRender();const stop=()=>void dwApi('stop',{workspaceId:w.id,runId:r.id}).catch(()=>{});signal?.addEventListener('abort',stop,{once:true});try{while(!r.settled){if(signal?.aborted||w.projectId&&!P(w.projectId)){await dwApi('stop',{workspaceId:w.id,runId:r.id});}await new Promise(ok=>setTimeout(ok,400));r=await dwApi('checkStatus',{workspaceId:w.id,runId:r.id});if(DW.current===w.id){DW.check=r;dwCheckPaint();}onProgress?.(r);}signal?.throwIfAborted();if(DW.current===w.id)dwRender();return r;}finally{signal?.removeEventListener('abort',stop);}}
async function dwAttach(){
 if(!DW.preview)throw new Error('目录已变化，请重新检查目录与脚本');
 const projectChoice=dwPanel.querySelector('[data-dw-project]').value,writable=dwPanel.querySelector('[data-dw-writable]').checked,allowChecks=dwPanel.querySelector('[data-dw-grant]').checked;let projectId=projectChoice;DW.allowWrite=writable;DW.allowChecks=allowChecks;
 if(projectChoice==='new'){
  const name=dwPanel.querySelector('[data-dw-project-name]').value.trim()||DW.preview.name+' · 开发',before=snap(),ids=new Set(state.projects.map(p=>p.id));HA.depth++;try{ACT['project.create']({name});const p=state.projects.find(p=>!ids.has(p.id));if(!p)throw new Error('没有观察到开发项目');projectId=p.id;DW.projectId=projectId;ACT['project.update']({projectId,summary:'在连接的源码仓库中分析、实现、验证并复核修改。源码写入与检查均有真实回执，模型绑定后才会推理。'});for(const [agent,name,role]of[['gpt','代码实现','读取实际源码，提出或实现小步修改'],['gemini','复核验证','检查差异、测试结果和可恢复性']]){const old=new Set(p.members.map(m=>m.id));ACT['member.add']({projectId,agent});const m=p.members.find(m=>!old.has(m.id));ACT['member.update']({projectId,memberId:m.id,name,role});}}finally{HA.depth--;HA.pending=before;save();historyCommit();renderAll();}
 }
 const w=await dwApi('attach',{directory:DW.preview.root,scriptsHash:DW.preview.scriptsHash,boardId:state.activeBoard,projectId,writable,allowChecks});closePan();DW.settings=false;DW.current=w.id;DW.projectId=projectId;await dwRefresh();await dwFiles();dwRender();hint('已连接实际源码；成员未绑定模型前不会推理');
}
CAT.push(['dev.gitDiff','读取当前文件真实Git差异，不重置已有修改','workspaceId,path,start?,count?'],['dev.open','打开已连接项目的源码面板，不授予新的目录权限','workspaceId?'],['dev.status','读取当前画板已连接的源码工作区及权限',''],['dev.files','列出已连接仓库的源码文件，可筛选分页','workspaceId,query?,page?'],['dev.read','读取真实源码和版本hash，可分页','workspaceId,path,start?,length?'],['dev.write','保存完整源码，必须用读取所得expectedHash；新文件用missing','workspaceId,path,content,expectedHash'],['dev.replace','在真实源码中精确替换唯一片段，必须提供版本hash','workspaceId,path,oldText,newText,expectedHash'],['dev.delete','删除源码文件并保留可恢复差异','workspaceId,path,expectedHash'],['dev.diff','读取实际修改记录，指定changeId可看前后正文','workspaceId,changeId?,start?,count?'],['dev.revert','回滚选定一次源码修改，拒绝覆盖后来人工编辑','workspaceId,changeId'],['dev.reapply','重做一次已回滚的源码修改','workspaceId,changeId'],['dev.check','运行已允许的typecheck/test/build并等待实际退出；不执行任意命令','workspaceId,command'],['dev.checkStatus','读取指定真实检查的状态和日志','workspaceId,runId'],['dev.stop','停止指定本机检查及其子进程','workspaceId,runId']);
const dwContextBase=asContext;asContext=function(){const c=dwContextBase();c.development=dwVisible().map(({id,name,boardId,projectId,writable,checksAllowed})=>({id,name,boardId:projectId?P(projectId).boardId:boardId,projectId,writable,checksAllowed}));return c;};
const dwPlanBase=asPlanRound;asPlanRound=async function(s,signal){await dwRefresh(signal);return dwPlanBase(s,signal);};
const dwInvokeBase=asInvoke;asInvoke=async function(name,a,ctx){
 if(!name.startsWith('dev.'))return dwInvokeBase(name,a,ctx);ctx.signal.throwIfAborted();await dwRefresh(ctx.signal);dwPanel.hidden=false;
 if(name==='dev.status'){dwRender();return{workspaces:asContext().development,message:'已读取已连接的真实源码工作区'};}
 const w=dwVisible().find(w=>w.id===a.workspaceId)||(!a.workspaceId?dwWorkspace():null);if(!w){dwRender();if(name==='dev.open')return{workspaces:[],message:'源码面板已打开，需要用户连接 Git 仓库'};throw new Error('请先由用户在源码面板选择并连接仓库；助手不能自行扩大目录权限');}DW.current=w.id;DW.settings=false;
 if(name==='dev.open'){await dwFiles();dwRender();return{workspaceId:w.id,message:'已展开源码开发面板'};}
 const action=name.slice(4),cp=ctx.step.checkpoint=ctx.step.checkpoint||{};cp.devRequestId=cp.devRequestId||crypto.randomUUID();asPersist();let r;
 if(['write','replace','delete'].includes(action))dwAssertClean(w,a.path);
 if(['revert','reapply'].includes(action)){const change=await dwApi('diff',{workspaceId:w.id,changeId:a.changeId},ctx.signal);dwAssertClean(w,change.path);}
 if(action==='read')r=await dwRead(w,a.path,a.start||0,a.length||12000);
 else if(action==='check'){
  r=cp.devRunId?await dwApi('checkStatus',{workspaceId:w.id,runId:cp.devRunId},ctx.signal):await dwApi('check',{workspaceId:w.id,command:a.command,requestId:cp.devRequestId},ctx.signal);cp.devRunId=r.id;asPersist();r=await dwFollowCheck(w,r,ctx.signal,c=>{ctx.session.runStatus=c.message;const el=$('#guide .as-status');if(el)el.textContent=c.message;});
 }else {const {start,count,...args}=a;r=await dwApi(action,{...args,workspaceId:w.id,...(['write','replace','delete'].includes(action)?{requestId:cp.devRequestId}:{})},ctx.signal);if(['write','replace','delete'].includes(action))await dwSaved(w,r);else if(action==='gitDiff'){DW.gitDiff=r;DW.tab='changes';dwRender();}else if(action==='diff'){DW.tab='changes';if(a.changeId)DW.change=r;else DW.changes=r.changes;dwRender();}else if(['revert','reapply'].includes(action)){await dwChanges();DW.change=await dwApi('diff',{workspaceId:w.id,changeId:r.id});DW.tab='changes';dwRender();}else if(action==='files'){DW.files=r.files;DW.total=r.total;DW.page=r.page;DW.query=a.query||'';DW.tab='files';dwRender();}else if(['checkStatus','stop'].includes(action)){DW.check=r;DW.tab='checks';dwRender();}}
 if(r.diff!==undefined)r={...r,diff:SoftwareToolsCore.page(r.diff,a.start,a.count)};
 if(r.before!==undefined)r={...r,before:SoftwareToolsCore.page(r.before||'',a.start,a.count),after:SoftwareToolsCore.page(r.after||'',a.start,a.count)};
 if(r.output!==undefined){const {output,...meta}=r;r={...meta,outputTail:output.slice(-12000),logTruncated:r.truncated||output.length>12000};}
 return AssistantCore.public({...r,message:r.message||'实际源码操作已完成：'+CAT.find(c=>c[0]===name)[1]});
};
ACT['dev.open']=a=>{void dwOpen(a?.projectId);return'已打开源码开发工作区'};
const dwPanBase=renderPan;renderPan=function(){dwPanBase();if(['boards','proj'].includes(panK)&&!$('#pan [data-dw-open]'))$('#pan').insertAdjacentHTML('beforeend',`<button data-dw-open="${panK==='proj'?esc(panId):''}">${icon('code',15)}源码开发</button>`);};
const dwRoomBase=renderRoom;renderRoom=function(){dwRoomBase();const toolbar=$('#room .rt');if(toolbar&&!toolbar.querySelector('[data-dw-open]'))toolbar.insertAdjacentHTML('beforeend',`<button data-dw-open="${esc(state.room)}">${icon('code',15)}源码</button>`);};
document.addEventListener('input',e=>{if(e.target.matches('[data-dw-editor]'))dwStoreDraft();if(e.target.matches('[data-dw-project-name]'))DW.newName=e.target.value;if(e.target.matches('[data-dw-directory]')){DW.directory=e.target.value;DW.preview=null;const button=dwPanel.querySelector('[data-dw-attach]');if(button)button.disabled=true;}if(e.target.matches('[data-dw-query]'))DW.query=e.target.value;});
document.addEventListener('change',e=>{if(e.target.matches('[data-dw-writable]'))DW.allowWrite=e.target.checked;if(e.target.matches('[data-dw-grant]'))DW.allowChecks=e.target.checked;if(e.target.matches('[data-dw-workspace]')){DW.current=e.target.value;DW.file=null;DW.check=null;void dwFiles().then(dwRender).catch(e=>hint(e.message));}});
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.a==='guide'){closePan();dwClose();}if(t.hasAttribute('data-dw-open')){void dwOpen(t.dataset.dwOpen);return;}if(!t.closest('#development')||![...t.attributes].some(a=>a.name.startsWith('data-dw-')))return;t.disabled=true;void(async()=>{DW.error='';const w=dwWorkspace();
 if(t.hasAttribute('data-dw-close'))return dwClose();
 if(t.hasAttribute('data-dw-other')){DW.settings=true;DW.preview=null;DW.directory='';DW.projectId=null;DW.allowWrite=false;DW.allowChecks=false;dwRender();return;}
 if(t.hasAttribute('data-dw-settings')){DW.settings=!DW.settings;DW.preview=null;DW.directory=w?.root||DW.directory;DW.allowWrite=!!w?.writable;DW.allowChecks=!!w?.checksAllowed;dwRender();return;}
 if(t.hasAttribute('data-dw-preview')){DW.directory=dwPanel.querySelector('[data-dw-directory]').value.trim();DW.preview=await dwApi('preview',{directory:DW.directory});dwRender();return;}
 if(t.hasAttribute('data-dw-attach'))return dwAttach();
 if(!w)throw new Error('先连接源码仓库');
 if(t.hasAttribute('data-dw-detach')){await dwApi('detach',{workspaceId:w.id});await dwRefresh();DW.file=null;DW.check=null;dwRender();return;}
 if(t.hasAttribute('data-dw-tab')){DW.tab=t.dataset.dwTab;if(DW.tab==='changes')await dwChanges();dwRender();return;}
 if(t.hasAttribute('data-dw-search')||t.hasAttribute('data-dw-page')){DW.page=t.dataset.dwPage?Math.max(1,DW.page+Number(t.dataset.dwPage)):1;await dwFiles();dwRender();return;}
 if(t.hasAttribute('data-dw-file')||t.hasAttribute('data-dw-read-path'))return dwRead(w,t.dataset.dwFile||dwPanel.querySelector('[data-dw-path]').value.trim());
 if(t.hasAttribute('data-dw-new')){const name=dwPanel.querySelector('[data-dw-path]').value.trim();if(!name)throw new Error('先填写相对文件路径');DW.file={path:name,hash:'missing',text:'',nextStart:null,total:0,dirty:true};DW.drafts[dwDraftId(w,name)]={...DW.file};dwSaveDrafts();dwRender();return;}
 if(t.hasAttribute('data-dw-discard')){const file=DW.file;delete DW.drafts[dwDraftId(w,file.path)];dwSaveDrafts();if(file.hash==='missing'){DW.file=null;dwRender();return;}return dwRead(w,file.path);}
 if(t.hasAttribute('data-dw-more')){if(DW.file.dirty)throw new Error('先处理本文件的手动草稿，再继续读取');return dwRead(w,DW.file.path,DW.file.nextStart);}
 if(t.hasAttribute('data-dw-save')||t.hasAttribute('data-dw-delete')||t.hasAttribute('data-dw-replace')){
  if(t.hasAttribute('data-dw-delete')&&DW.file.hash==='missing'){delete DW.drafts[dwDraftId(w,DW.file.path)];dwSaveDrafts();DW.file=null;dwRender();return;}
  const action=t.hasAttribute('data-dw-save')?'write':t.hasAttribute('data-dw-delete')?'delete':'replace';if(action!=='write')dwAssertClean(w,DW.file.path);
  const args={workspaceId:w.id,path:DW.file.path,expectedHash:DW.file.hash,requestId:crypto.randomUUID()};if(action==='write')args.content=dwPanel.querySelector('[data-dw-editor]').value;if(action==='replace'){args.oldText=dwPanel.querySelector('[data-dw-old]').value;args.newText=dwPanel.querySelector('[data-dw-new-text]').value;}
  return dwSaved(w,await dwApi(action,args));
 }
 if(t.hasAttribute('data-dw-git')){if(w.kind==='practice'){await dwChanges();DW.tab='changes';dwRender();return;}DW.gitDiff=await dwApi('gitDiff',{workspaceId:w.id,path:DW.file.path});DW.tab='changes';await dwChanges();dwRender();return;}
 if(t.hasAttribute('data-dw-refresh-changes')){await dwChanges();dwRender();return;}
 if(t.hasAttribute('data-dw-diff')){DW.change=await dwApi('diff',{workspaceId:w.id,changeId:t.dataset.dwDiff});dwRender();return;}
 if(t.hasAttribute('data-dw-revert')||t.hasAttribute('data-dw-reapply')){const action=t.hasAttribute('data-dw-revert')?'revert':'reapply',id=t.dataset.dwRevert||t.dataset.dwReapply,change=DW.changes.find(c=>c.id===id);if(change)dwAssertClean(w,change.path);await dwApi(action,{workspaceId:w.id,changeId:id});await dwChanges();DW.change=await dwApi('diff',{workspaceId:w.id,changeId:id});if(DW.file?.path===change?.path)DW.file=null;await dwFiles();dwRender();return;}
 if(t.hasAttribute('data-dw-check')){const r=await dwApi('check',{workspaceId:w.id,command:t.dataset.dwCheck,requestId:crypto.randomUUID()});return dwFollowCheck(w,r);}
 if(t.hasAttribute('data-dw-stop')&&DW.check){DW.check=await dwApi('stop',{workspaceId:w.id,runId:DW.check.id});dwCheckPaint();}
 })().catch(e=>{DW.error=e.message||String(e);dwRender();hint(DW.error);}).finally(()=>{if(t.isConnected)t.disabled=false;});});
